function parseRichText(prop) {
  if (!prop?.rich_text) return "";

  return prop.rich_text
    .map(t => t.plain_text)
    .join("")
    .trim();
}

function parseTitle(prop) {
  if (!prop?.title) return "";

  return prop.title
    .map(t => t.plain_text)
    .join("")
    .trim();
}

function parseSelect(prop) {
  return prop?.select?.name || null;
}

function parseMultiSelect(prop) {
  return prop?.multi_select?.map(s => s.name) || [];
}

function parseNumber(prop) {
  return prop?.number ?? null;
}

function parseDate(prop) {
  return prop?.date?.start ?? null;
}

function parseCheckbox(prop) {
  return prop?.checkbox ?? false;
}

function parseProperty(prop) {

  if (!prop) return null;

  switch (prop.type) {

    case "title":
      return parseTitle(prop);

    case "rich_text":
      return parseRichText(prop);

    case "number":
      return parseNumber(prop);

    case "select":
      return parseSelect(prop);

    case "multi_select":
      return parseMultiSelect(prop);

    case "date":
      return parseDate(prop);

    case "checkbox":
      return parseCheckbox(prop);

    default:
      return null;
  }
}

return items.map(item => {

  const props = item.json.properties;
  const result = {};

  for (const key in props) {
    result[key.toLowerCase()] = parseProperty(props[key]);
  }

  // Special parsing for JSON fields
  let structured_requirements = {};

  try {
    structured_requirements = JSON.parse(result.structured_requirements || "{}");
  } catch (e) {
    console.error("Structured JSON parse error", e);
  }

  return {
    json: {
      job_page_id: item.json.id,
      ...result,
      structured_requirements
    }
  };

});

/*
Loading dictionaries
*/

const fs = require("fs");
const path = require("path");

const DICT_PATH = "/PATH/TO/RESUME_SYSTEM_ROOT/builds/dictionaries";
const VOCAB_PATH = "/PATH/TO/RESUME_SYSTEM_ROOT/builds/vocab_learning";

const PHRASE_MAP = JSON.parse(
  fs.readFileSync(path.join(DICT_PATH,"phrase_map.json"),"utf8")
);

const TOKEN_MAP = JSON.parse(
  fs.readFileSync(path.join(DICT_PATH,"token_map.json"),"utf8")
);

const DOMAIN_SIGNALS = JSON.parse(
  fs.readFileSync(path.join(DICT_PATH,"domain_signals.json"),"utf8")
);

const STOPWORDS = new Set(
  JSON.parse(
    fs.readFileSync(path.join(DICT_PATH,"stopwords.json"),"utf8")
  )
);

/**
 Bigram loader
 */
const BIGRAM_CANDIDATE_FILE =
  path.join(VOCAB_PATH,"jd_bigram_candidates.json");

let BIGRAM_CANDIDATES = {};

try {

  const raw = fs.readFileSync(BIGRAM_CANDIDATE_FILE,"utf8");

  if(raw.trim()){
    BIGRAM_CANDIDATES = JSON.parse(raw);
  }

} catch(e){

  BIGRAM_CANDIDATES = {};

}
// Bigram generator

function extractBigrams(tokens){

  const bigrams = [];

  for(let i=0;i<tokens.length-1;i++){

    const t1 = tokens[i];
    const t2 = tokens[i+1];

    if(STOPWORDS.has(t1)) continue;
    if(STOPWORDS.has(t2)) continue;

    if(NOISE.has(t1)) continue;
    if(NOISE.has(t2)) continue;

    const phrase = `${t1}_${t2}`;

    bigrams.push(phrase);

  }

  return bigrams;

}
//Bigram capture
function captureUnknownBigrams(bigrams,context){

  for(const phrase of bigrams){

    if(KNOWN_VOCAB.has(phrase)) continue;

    if(!BIGRAM_CANDIDATES[phrase]){

      BIGRAM_CANDIDATES[phrase] = {
        count:0,
        examples:[]
      };

    }

    BIGRAM_CANDIDATES[phrase].count++;

    if(BIGRAM_CANDIDATES[phrase].examples.length < 5){

      BIGRAM_CANDIDATES[phrase].examples.push(context);

    }

  }

}
// token sorter before file append 
function sortCandidateDict(dict){

  return Object.fromEntries(
    Object.entries(dict)
      .sort((a,b) => b[1].count - a[1].count)
  );

}
/*
Candidate store
*/

const CANDIDATE_FILE =
  path.join(VOCAB_PATH,"jd_token_candidates.json");

let TOKEN_CANDIDATES = {};

try {

  const raw = fs.readFileSync(CANDIDATE_FILE,"utf8");

  if(raw.trim()){
    TOKEN_CANDIDATES = JSON.parse(raw);
  }

} catch(e){

  TOKEN_CANDIDATES = {};

}

/*
Known vocabulary
*/

const KNOWN_VOCAB = new Set([
  ...Object.values(PHRASE_MAP),
  ...Object.keys(TOKEN_MAP),
  ...Object.values(TOKEN_MAP),
  ...Object.values(DOMAIN_SIGNALS).flat()
]);

const NOISE = new Set([
"team","organization","initiative",
"program","support","environment",
"experience","ability"
]);

/*
Helpers
*/

function normalizePhrases(text){

  let normalized = (text || "").toLowerCase();

  const phrases = Object.keys(PHRASE_MAP)
    .sort((a,b)=>b.length-a.length);

  for(const phrase of phrases){

    normalized =
      normalized.replaceAll(phrase,PHRASE_MAP[phrase]);

  }

  return normalized;

}

function tokenize(text){

  return (text || "")
    .toLowerCase()
    .replace(/[^\w\s]/g," ")
    .split(/\s+/)
    .filter(w => w.length > 2 && !STOPWORDS.has(w));

}

function normalizeTokens(tokens){

  return tokens.map(t => TOKEN_MAP[t] || t);

}

function extractTokens(text){

  const phraseNormalized =
    normalizePhrases(text);

  const tokens =
    tokenize(phraseNormalized);

  const normalized =
    normalizeTokens(tokens);

  return normalized;

}

/*
Vocabulary learning
*/

function captureUnknownTokens(tokens,context){

  for(const token of tokens){

    if(token.length < 3) continue;

    if(KNOWN_VOCAB.has(token)) continue;

    if(NOISE.has(token)) continue;

    if(!TOKEN_CANDIDATES[token]){

      TOKEN_CANDIDATES[token] = {
        count:0,
        examples:[]
      };

    }

    TOKEN_CANDIDATES[token].count++;

    if(TOKEN_CANDIDATES[token].examples.length < 5){

      TOKEN_CANDIDATES[token].examples.push(context);

    }

  }

}

function persistCandidates(){

  const sortedTokens =
    sortCandidateDict(TOKEN_CANDIDATES);

  const sortedBigrams =
    sortCandidateDict(BIGRAM_CANDIDATES);

  fs.writeFileSync(
    CANDIDATE_FILE,
    JSON.stringify(sortedTokens,null,2)
  );

  fs.writeFileSync(
    BIGRAM_CANDIDATE_FILE,
    JSON.stringify(sortedBigrams,null,2)
  );

}

/*
Projection engine
*/

const MIN_BULLETS = 6;

const DOMAIN_PRIORITY = {

  cloud: [
    "cloud_security",
    "identity_security"
  ],

  grc: [
    "risk_management",
    "security_governance",
    "security_compliance"
  ],

  privacy: [
    "data_privacy"
  ],

  soc: [
    "security_operations"
  ]

};

/*
Requirement token extraction
*/

function buildRequirementTokens(reqs){

  return reqs.map(r => {

   const tokens = extractTokens(r);

    /* capture single tokens */

    captureUnknownTokens(tokens,r);

    /* generate bigrams */

    const bigrams = extractBigrams(tokens);

    /* capture phrases */

captureUnknownBigrams(bigrams,r);

    return {
      text:r,
      tokens:tokens
    };

  });

}
function inferDomains(reqTokens){

  const domainScores = {};

  for(const domain of Object.keys(DOMAIN_SIGNALS)){
    domainScores[domain] = 0;
  }

  for(const r of reqTokens){

    for(const token of r.tokens){

      for(const [domain,signals] of Object.entries(DOMAIN_SIGNALS)){

        if(signals.includes(token)){
          domainScores[domain]++;
        }

      }

    }

  }

  /*
  Risk mitigation: ignore weak domains
  */

  const filtered = {};

  for(const [domain,score] of Object.entries(domainScores)){

    if(score >= 2){
      filtered[domain] = score;
    }

  }

  return filtered;

}
/*
Bullet scoring
*/

function scoreBullet(bullet, reqTokens, roleCluster, jdDomains){

  const textTokens = extractTokens(bullet.text);

  const tags = bullet.tags || [];
  const o = bullet.ontology || {};

  let score = 0;

  /*
  Token overlap
  */

  for(const r of reqTokens){

    for(const t of r.tokens){

      if(textTokens.includes(t))
        score += 3;

    }

  }

  /*
  Tag boost
  */

  for(const tag of tags){

    if(reqTokens.some(r => r.tokens.includes(tag)))
      score += 4;

  }

  /*
  JD domain boost
  */

  if(jdDomains[o.domain]){

    const domainWeight = jdDomains[o.domain];

    /*
    Risk mitigation: cap domain boost
    */

    score += Math.min(domainWeight * 2,6);

  }

  return score;

}

/*
Selection
*/

function selectBullets(bullets, reqTokens, roleCluster, jdDomains){

  const scored = bullets
    .map(b => ({
      bullet:b,
      score:scoreBullet(b,reqTokens,roleCluster, jdDomains)
    }))
    .sort((a,b)=>b.score-a.score);

  return scored
    .slice(0,MIN_BULLETS)
    .map(x=>x.bullet);

}

/*
Skill builder
*/

function buildSkills(canonical, bullets){

  const skills = canonical.skills || [];
  const tools = canonical.tools || [];
  const frameworks = canonical.frameworks || [];

  const signals = new Set([
    ...bullets.flatMap(b => b.tags || [])
  ]);

  const cloudBucket = [];
  const grcBucket = [];

  const cloudSignals = [
    "azure","rbac","iam","pim","network",
    "segmentation","keyvault","encryption",
    "sentinel","identity","cloud"
  ];

  const grcSignals = [
    "risk","nist","iso","soc","gdpr",
    "audit","compliance","policy","governance"
  ];

  const all = [...skills,...tools,...frameworks];
  const uniqueSkills = [...new Set(all)];

  for(const skill of uniqueSkills){

    const s = skill.toLowerCase();

    if(cloudSignals.some(sig => s.includes(sig))){
      cloudBucket.push(skill);
    }
    else if(grcSignals.some(sig => s.includes(sig))){
      grcBucket.push(skill);
    }
    else{
      cloudBucket.push(skill);
    }

  }

  function rank(list){

    return list
      .map(skill => ({
        skill,
        score:[...signals].some(sig =>
          skill.toLowerCase().includes(sig)
        ) ? 3 : 0
      }))
      .sort((a,b)=>b.score-a.score)
      .map(x=>x.skill)
      .slice(0,15);

  }

  return {

    "Cloud & Security": rank(cloudBucket),
    "Risk, Governance & Compliance": rank(grcBucket)

  };

}

/*
Main
*/

return items.map(item => {

  const job = item.json;

const canonical = job.canonical_profile_object || {};
const structured = job.structured_requirements || {};

const roleCluster =
  structured.role_cluster_hint || "general";

/*
STEP 1 — extract JD tokens
*/

const reqTokens =
  buildRequirementTokens(structured.must_have || []);

/*
STEP 2 — infer JD domains
*/

const jdDomains =
  inferDomains(reqTokens);

/*
STEP 3 — get bullet bank
*/

const bulletBank =
  canonical.bullet_bank || [];

  const professional =
    bulletBank.filter(b =>
      b.experience !== "industrial_training"
    );

  const training =
    bulletBank.filter(b =>
      b.experience === "industrial_training"
    );

  const selected =
    selectBullets(professional,reqTokens,roleCluster, jdDomains);

  const industrialTraining =
    training.slice(0,3).map(b=>({
      id:b.id,
      text:b.text,
      tags:b.tags || [],
      clusters:b.clusters || [],
      ontology:b.ontology
    }));

  const skills =
    buildSkills(canonical,selected);

  persistCandidates();

  return {

    json:{
      ...job,

      projection:{

        selected_bullets:selected,

        industrial_training_bullets:industrialTraining,

        skills:skills,

        coverage_score:
          selected.length / MIN_BULLETS,

        debug: {

  domains:selected.map(b => b.ontology?.domain),

  clusters:selected.flatMap(b => b.clusters || []),

  jd_domains: jdDomains

}

      }

    }

  };

});

// =====================================
// Prepare Resume Generation Payload
// Runs once for all items
// =====================================

return items.map(item => {

  const job = item.json;
  const projection = job.projection || {};
  const structured = job.structured_requirements || {};

  // Preserve bullet structure (text + ontology)
  const bullets = (projection.selected_bullets || [])
    .map(b => typeof b === "string" ? { text: b } : b)
    .filter(b => b.text);

  const industrial_bullets = (projection.industrial_training_bullets || [])
    .map(b => typeof b === "string" ? { text: b } : b)
    .filter(b => b.text);

  const skills = projection.skills || {};

  const mustHave = structured.must_have || [];
  const niceToHave = structured.nice_to_have || [];
  const page_id = job.job_page_id;

  return {
    json: {

      // -------- JOB CONTEXT --------
      job_title: job.job_title,
      company: job.company,
      role_cluster: structured.role_cluster_hint || "general",
      job_page_id: page_id,

      // -------- REQUIREMENTS --------
      requirements: {
        must_have: mustHave,
        nice_to_have: niceToHave
      },

      // -------- PROJECTION OUTPUT --------
      evidence_bullets: bullets,
      industrial_training_bullets: industrial_bullets,
      projected_skills: skills,

      // -------- METRICS --------
      coverage_score: projection.coverage_score || 0,

      // -------- DEBUG --------
      matched_requirements: projection.matched_requirements || []

    }
  };

});

return items.map(item => {

  const d = item.json;

  return {

    json: {

      job_page_id: d.job_page_id,
      company: d.company,

      professional_bullets:
        d.llm_output.optimized_professional_bullets || [],

      training_bullets:
        d.llm_output.optimized_training_bullets || [],

      skills:
        d.projection_engine?.skills || {},

      role_cluster: d.role_cluster,

      coverage_score:
        d.projection_engine?.coverage_score ?? null

    }

  };

});

// ======================================
// Ollama JSON Parser
// Run Once For All Items
// ======================================

const output = [];

for (const item of items) {

  const job = item.json;

  const raw =
    job.message?.content ||
    job.response ||
    job.content ||
    "";

  let jsonText = raw;

  // ----------------------------
  // Extract JSON block safely
  // ----------------------------

  const firstBrace = raw.indexOf("{");
  const lastBrace = raw.lastIndexOf("}");

  if (firstBrace !== -1 && lastBrace !== -1) {
    jsonText = raw.slice(firstBrace, lastBrace + 1);
  }

  let parsed;
  let parse_error = false;

  try {

    parsed = JSON.parse(jsonText);

  } catch (e) {

    parse_error = true;

    output.push({
      json: {
        ok: false,
        error_type: "llm_parse_error",
        error: e.message,
        raw_preview: raw.slice(0, 500),
        ...job
      }
    });

    continue;
  }

  // ----------------------------
  // Validate structure
  // ----------------------------

  if (!Array.isArray(parsed.optimized_professional_bullets)) {

    output.push({
      json: {
        ok: false,
        error_type: "Professional bullet array has invalid_structure",
        parsed,
        ...job
      }
    });

    continue;
  }



  // ----------------------------
  // Success case
  // ----------------------------

  output.push({
    json: {
      ok: true,
      optimized_professional_bullets: parsed.optimized_professional_bullets,
      optimized_training_bullets: parsed.optimized_training_bullets,
      ...job
    }
  });

}

return output;

// ============================================
// Debug Bundle Builder
