for (let i = 0; i < jobs.length; i++) {

  const job = payloadItems[i]?.json || {};
  const projection = projectionItems[i]?.json?.projection || {};
  const llmPrompt = llmPromptItems[i]?.json || {};
  const llmParsed = jobs[i] || {};

