    structured_requirements: job.requirements,

    projection_engine: {

      selected_bullets: projection.selected_bullets || [],
      matched_requirements: projection.matched_requirements || [],
      skills: projection.skills || [],
      coverage_score: projection.coverage_score ?? null

    },

    llm_prompt: {

      system: llmPrompt.messages?.[0]?.content || "",
      user: llmPrompt.messages?.[1]?.content || ""

    },

    llm_output: {

      optimized_professional_bullets:
        llmParsed.optimized_professional_bullets || [],

      optimized_training_bullets:
        llmParsed.optimized_training_bullets || []

    }

  };

  bundles.push({ json: bundle });

